package com.procurement.approvaltask.specification; import com.procurement.approvaltask.entity.*; import org.springframework.data.jpa.domain.Specification; public final class ApprovalTaskSpecification{private ApprovalTaskSpecification(){}public static Specification<ApprovalTask> search(Long requestId,Long employeeId,ApprovalTaskStatus status){return(r,q,b)->{var p=b.conjunction();if(requestId!=null)p=b.and(p,b.equal(r.get("purchaseRequest").get("id"),requestId));if(employeeId!=null)p=b.and(p,b.equal(r.get("assignedEmployee").get("id"),employeeId));if(status!=null)p=b.and(p,b.equal(r.get("status"),status));return p;};}}
